/* ================================================================
   VERIFICATION
   ================================================================ */
SELECT c.capability_id, c.capability_pk, ec.capability_version_pk,
       (SELECT COUNT(*) FROM model.capability_scenario cs WHERE cs.capability_version_pk = ec.capability_version_pk) AS scenarios,
       (SELECT COUNT(*) FROM model.capability_root_scenario r WHERE r.capability_version_pk = ec.capability_version_pk) AS roots
FROM model.capability c
JOIN model.estate_capability ec ON ec.capability_pk = c.capability_pk AND ec.estate_model_pk = @estate_model_pk
WHERE c.capability_id LIKE '%equity%'
ORDER BY c.capability_id;

-- The capsule digest must resolve to exactly one candidate per capability,
-- which is what capability-embodiment.sql requires.
SELECT c.capability_id,
       (SELECT COUNT(DISTINCT a.capsule_digest)
          FROM source.source_lineage l
          JOIN source.source_observation o ON o.source_observation_pk = l.source_observation_pk
          JOIN source.source_appearance a ON a.source_appearance_pk = o.source_appearance_pk
         WHERE l.semantic_object_definition_pk = ec.semantic_object_definition_pk
           AND a.estate_snapshot_pk = @snap AND a.source_class = 'MANAGED_CAPSULE'
           AND a.capsule_digest IS NOT NULL) AS capsule_candidates_expect_1,
       (SELECT COUNT(*) FROM source.source_appearance a2
         WHERE a2.estate_snapshot_pk = @snap AND a2.source_path COLLATE DATABASE_DEFAULT LIKE N'capabilities/' + c.capability_id COLLATE DATABASE_DEFAULT + N'/%') AS entries
FROM model.capability c
JOIN model.estate_capability ec ON ec.capability_pk = c.capability_pk AND ec.estate_model_pk = @estate_model_pk
WHERE c.capability_id LIKE '%equity%'
ORDER BY c.capability_id;

-- Every inserted content object must hash to its stored digest.
SELECT COUNT(*) AS content_objects_with_bad_digest_expect_0
FROM source.content_object
WHERE content_digest <> HASHBYTES('SHA2_256', content_bytes);

ROLLBACK TRANSACTION;
